previewCss:
.darma-loader-three-dots-windmill{
  --td-dot: calc(var(--loader-size, 56px) / 5.6);
  --td-arm: calc(var(--loader-size, 56px) / 3.2);
  position:relative;
  display:inline-block;
  width:var(--td-dot);
  height:var(--td-dot);
  border-radius:50%;
  background-color:var(--loader-color, #6366f1);
  animation:darma-loader-three-dots-windmill-td-windmill var(--loader-speed, 2s) infinite ease-in-out;
}
.darma-loader-three-dots-windmill::before,
.darma-loader-three-dots-windmill::after{
  content:"";
  position:absolute;
  top:0;
  left:0;
  width:var(--td-dot);
  height:var(--td-dot);
  border-radius:50%;
  background-color:var(--loader-secondary-color, #a5b4fc);
}
.darma-loader-three-dots-windmill::before{transform:rotate(120deg) translateY(calc(var(--td-arm) * -1))}
.darma-loader-three-dots-windmill::after{transform:rotate(240deg) translateY(calc(var(--td-arm) * -1))}
@keyframes darma-loader-three-dots-windmill-td-windmill{
  0%{transform:rotate(0deg)}
  50%{transform:rotate(180deg)}
  100%{transform:rotate(360deg)}
}

